INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('6bacbb89-1a44-57be-9e7a-906691c87e39', '2a37052e-e854-5df4-aebd-58ca22610d12', '0800e79c-9e90-5df8-bd45-4bcdac047d4b', '96d4c426-5e2e-58d3-95a1-ef3bc23ea6a3', 'seminar', '/ˈsemɪnɑː(r)/', 'B2', 'noun', 'buổi hội thảo hoặc lớp học nhỏ để thảo luận về một chủ đề cụ thể.', 'a meeting where a small group of people discuss a specific subject with an expert.', 'She attended a seminar on digital marketing strategies last week.', 'Cô ấy đã tham dự một buổi hội thảo về các chiến lược tiếp thị kỹ thuật số vào tuần trước.', '{\"en\": \"All staff members are required to attend the training seminar regarding new safety protocols tomorrow.\", \"vi\": \"Tất cả nhân viên được yêu cầu tham dự buổi hội thảo đào tạo về các quy định an toàn mới vào ngày mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/seminar-ljspeech-649ccf04.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/seminar-cori-649ccf04.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/seminar-bc51ab64.webp', '[\"workshop\", \"conference\"]', NULL, '[{\"phrase\": \"attend a seminar\", \"meaning\": \"tham dự hội thảo\"}, {\"phrase\": \"hold a seminar\", \"meaning\": \"tổ chức hội thảo\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/seminar-cori-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru0-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru5-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru6-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru10-649ccf04.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/seminar-aru9-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru3-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru7-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru8-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-aru2-649ccf04.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/seminar-ljspeech-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt408-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt138-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt624-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt396-649ccf04.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/seminar-lt498-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt132-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt288-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt42-649ccf04.mp3\", \"/storage/v1/object/public/pronunciation/v2/seminar-lt90-649ccf04.mp3\"]}}', 'Seminar thường mang tính học thuật hoặc đào tạo chuyên sâu.', 'office', 1, 0),
('fee33610-5198-5aa5-802f-d676b6dcc297', '2a37052e-e854-5df4-aebd-58ca22610d12', '0800e79c-9e90-5df8-bd45-4bcdac047d4b', '96d4c426-5e2e-58d3-95a1-ef3bc23ea6a3', 'dedicated', 'UK: /ˈdɛdɪkeɪtɪd/ | US: /ˈdɛdɪˌkeɪtɪd/', 'B2', 'adjective', 'dành riêng, chuyên dụng', 'Giving all your energy and attention to a particular job or activity.', 'The team is dedicated to providing excellent customer service.', 'Đội ngũ tận tâm cung cấp dịch vụ khách hàng xuất sắc.', '{\"en\": \"Ms. Dupont is a dedicated server manager who spent the entire weekend resolving the network outage.\", \"vi\": \"Cô Dupont là một quản lý máy chủ tận tụy, người đã dành cả cuối tuần để xử lý sự cố mạng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/dedicated-ljspeech-0d30712f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/dedicated-cori-0d30712f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/dedicated-b8c64595.webp', '[\"committed\", \"devoted\", \"exclusive\"]', '[\"indifferent\", \"apathetic\", \"uncommitted\"]', '[{\"phrase\": \"dedicated server\", \"meaning\": \"máy chủ dùng riêng\"}, {\"phrase\": \"be dedicated to\", \"meaning\": \"tận tụy / dành riêng cho\"}]', '[{\"word\": \"addicted\", \"note_vi\": \"nghiện (thường mang nghĩa tiêu cực), khác với dedicated (tận tụy, cống hiến)\"}]', '[{\"pos\": \"verb\", \"word\": \"dedicate\"}, {\"pos\": \"noun\", \"word\": \"dedication\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/dedicated-cori-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru0-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru5-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru6-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru10-0d30712f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/dedicated-aru9-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru3-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru7-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru8-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-aru2-0d30712f.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/dedicated-ljspeech-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt408-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt138-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt624-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt396-0d30712f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/dedicated-lt498-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt132-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt288-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt42-0d30712f.mp3\", \"/storage/v1/object/public/pronunciation/v2/dedicated-lt90-0d30712f.mp3\"]}}', 'Thường dùng với cấu trúc \'be dedicated to + V-ing/N\' (tận tụy làm gì / dành riêng cho cái gì). Sau \'to\' là danh từ hoặc danh động từ.', 'human resources', 1, 1),
('8638992e-fa06-5c59-a247-1800aaf26c43', '2a37052e-e854-5df4-aebd-58ca22610d12', '0800e79c-9e90-5df8-bd45-4bcdac047d4b', '96d4c426-5e2e-58d3-95a1-ef3bc23ea6a3', 'chase', '/tʃeɪs/', 'B2', 'noun', 'Hành động đuổi theo ai đó hoặc cái gì đó.', 'the act of running after someone or something to catch them.', 'The police car was involved in a high-speed chase through the city streets.', 'Chiếc xe cảnh sát đã tham gia vào một cuộc rượt đuổi tốc độ cao qua các con phố thành phố.', '{\"en\": \"The security guards began a chase after the shoplifter ran out of the store.\", \"vi\": \"Các nhân viên bảo vệ đã bắt đầu đuổi theo sau khi kẻ trộm đồ chạy ra khỏi cửa hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/chase-ljspeech-702b78f4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/chase-cori-702b78f4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/chase-da12ed20.webp', '[\"pursuit\", \"hunt\"]', NULL, '[{\"phrase\": \"wild goose chase\", \"meaning\": \"sự tìm kiếm vô vọng\"}, {\"phrase\": \"give chase\", \"meaning\": \"đuổi theo\"}]', '[{\"word\": \"race\", \"note_vi\": \"race là cuộc đua tốc độ, chase là sự đuổi theo để bắt giữ.\"}]', '[{\"pos\": \"verb\", \"word\": \"chase\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/chase-cori-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru0-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru5-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru6-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru10-702b78f4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/chase-aru9-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru3-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru7-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru8-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-aru2-702b78f4.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/chase-ljspeech-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt408-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt138-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt624-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt396-702b78f4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/chase-lt498-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt132-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt288-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt42-702b78f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/chase-lt90-702b78f4.mp3\"]}}', 'Thành ngữ \'cut to the chase\' cực kỳ phổ biến trong các cuộc họp công sở.', 'shopping', 1, 2),
('4a3af288-4b80-54ce-8e62-b4ef358dfa2d', '2a37052e-e854-5df4-aebd-58ca22610d12', '0800e79c-9e90-5df8-bd45-4bcdac047d4b', '96d4c426-5e2e-58d3-95a1-ef3bc23ea6a3', 'implication', '/ˌɪmplɪˈkeɪʃn/', 'B2', 'noun', 'Điều được ngụ ý hoặc gợi ý nhưng không được nói rõ ràng.', 'something that is suggested or indirectly stated without being said directly.', 'The manager\'s silence had serious implications for the future of the project.', 'Sự im lặng của người quản lý có những hàm ý nghiêm trọng đối với tương lai của dự án.', '{\"en\": \"The board discussed the financial implications of the new tax policy on our sales.\", \"vi\": \"Ban giám đốc đã thảo luận về những ảnh hưởng tài chính của chính sách thuế mới đối với doanh số của chúng ta.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/implication-ljspeech-5a5f4a3a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/implication-cori-5a5f4a3a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/implication-23faedd1.webp', '[\"suggestion\", \"inference\", \"consequence\"]', '[\"explicitness\"]', '[{\"phrase\": \"financial implications\", \"meaning\": \"hệ quả tài chính\"}, {\"phrase\": \"serious implications\", \"meaning\": \"hệ quả nghiêm trọng\"}]', '[{\"word\": \"complication\", \"note_vi\": \"complication là sự phức tạp, rắc rối phát sinh\"}]', '[{\"pos\": \"verb\", \"word\": \"imply\"}, {\"pos\": \"adjective\", \"word\": \"implicit\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/implication-cori-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru0-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru5-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru6-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru10-5a5f4a3a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/implication-aru9-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru3-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru7-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru8-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-aru2-5a5f4a3a.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/implication-ljspeech-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt408-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt138-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt624-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt396-5a5f4a3a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/implication-lt498-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt132-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt288-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt42-5a5f4a3a.mp3\", \"/storage/v1/object/public/pronunciation/v2/implication-lt90-5a5f4a3a.mp3\"]}}', 'Tránh nhầm với complication (sự phức tạp). Implication là ẩn ý hoặc hệ quả gián tiếp.', 'business', 1, 3),
('42d43c86-430d-54a1-9dbe-cda14b2f971e', '2a37052e-e854-5df4-aebd-58ca22610d12', '0800e79c-9e90-5df8-bd45-4bcdac047d4b', '96d4c426-5e2e-58d3-95a1-ef3bc23ea6a3', 'boost', '/buːst/', 'B2', 'verb', 'Giúp tăng lên, cải thiện hoặc thúc đẩy điều gì đó.', 'to make something become better, larger, or more successful than it was before.', 'The new marketing campaign aims to boost sales by 20%.', 'Chiến dịch marketing mới nhằm mục đích tăng doanh số lên 20%.', '{\"en\": \"The company decided to offer discounts to boost the number of customers this month.\", \"vi\": \"Công ty quyết định giảm giá để thúc đẩy số lượng khách hàng trong tháng này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/boost-ljspeech-f7d80df0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/boost-cori-f7d80df0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/boost-69100372.webp', '[\"improve\", \"increase\"]', '[\"decrease\", \"reduce\"]', '[{\"phrase\": \"boost sales\", \"meaning\": \"tăng doanh số\"}, {\"phrase\": \"boost productivity\", \"meaning\": \"tăng năng suất\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"booster\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/boost-cori-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru0-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru5-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru6-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru10-f7d80df0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/boost-aru9-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru3-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru7-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru8-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-aru2-f7d80df0.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/boost-ljspeech-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt408-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt138-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt624-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt396-f7d80df0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/boost-lt498-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt132-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt288-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt42-f7d80df0.mp3\", \"/storage/v1/object/public/pronunciation/v2/boost-lt90-f7d80df0.mp3\"]}}', 'Thường dùng trong ngữ cảnh kinh doanh để nói về việc cải thiện hiệu suất hoặc doanh thu.', 'business', 1, 4),
('f08cad75-2a66-5ebd-bb20-630880a1a869', '2a37052e-e854-5df4-aebd-58ca22610d12', '0800e79c-9e90-5df8-bd45-4bcdac047d4b', '96d4c426-5e2e-58d3-95a1-ef3bc23ea6a3', 'speculation', '/ˌspekjuˈleɪʃn/', 'C1', 'noun', 'Sự phỏng đoán hoặc suy nghĩ về điều gì đó mà không có đủ bằng chứng.', 'the act of guessing about the future or the reasons for something without facts.', 'There was much speculation about the cause of the sudden market crash.', 'Có nhiều suy đoán về nguyên nhân của sự sụp đổ thị trường đột ngột.', '{\"en\": \"There is much speculation among investors regarding the potential merger of the two companies.\", \"vi\": \"Có nhiều sự phỏng đoán giữa các nhà đầu tư liên quan đến việc sáp nhập tiềm năng của hai công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/speculation-ljspeech-e334ea0d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/speculation-cori-e334ea0d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/speculation-ba6434fd.webp', '[\"guess\", \"conjecture\"]', '[\"fact\", \"certainty\"]', '[{\"phrase\": \"market speculation\", \"meaning\": \"đầu cơ thị trường\"}, {\"phrase\": \"idle speculation\", \"meaning\": \"suy đoán vô căn cứ\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"speculate\"}, {\"pos\": \"adjective\", \"word\": \"speculative\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/speculation-cori-e334ea0d.mp3\", \"/storage/v1/object/public/pronunciation/v2/speculation-aru0-e334ea0d.mp3\", \"/storage/v1/object/public/pronunciation/v2/speculation-aru5-e334ea0d.mp3\", \"/storage/v1/object/public/pronunciation/v2/speculation-aru6-e334ea0d.mp3\", \"/storage/v1/object/public/pronunciation/v2/speculation-aru10-e334ea0d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/speculation-aru9-e334ea0d.mp3\", \"/storage/v1/object/public/pronunciation/v2/speculation-aru3-e334ea0d.mp3\", \"/storage/v1/object/public/pronunciation/v2/speculation-aru7-e334ea0d.mp3\", \"/storage/v1/obj