('92434f1a-576b-503a-a685-ded9874be01c', '2a37052e-e854-5df4-aebd-58ca22610d12', '5725bd42-be2e-54a4-8a40-76d80630510c', '954a2918-cd0c-5f7c-8bf2-5ec1fff06698', 'assistance', '/əˈsɪstəns/', 'B1', 'noun', 'Hành động hoặc sự giúp đỡ được cung cấp cho ai đó.', 'help or support given to someone who needs it.', 'Please don\'t hesitate to ask for assistance if you need help.', 'Xin đừng ngần ngại yêu cầu sự giúp đỡ nếu bạn cần.', '{\"en\": \"Our customer service team is available to provide assistance with any order issues.\", \"vi\": \"Đội ngũ dịch vụ khách hàng của chúng tôi luôn sẵn sàng hỗ trợ mọi vấn đề về đơn hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assistance-ljspeech-9e8a01f2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assistance-cori-9e8a01f2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/assistance-7a7f5c96.webp', '[\"help\", \"support\", \"aid\"]', NULL, '[{\"phrase\": \"provide assistance\", \"meaning\": \"cung cấp sự hỗ trợ\"}, {\"phrase\": \"technical assistance\", \"meaning\": \"hỗ trợ kỹ thuật\"}, {\"phrase\": \"financial assistance\", \"meaning\": \"hỗ trợ tài chính\"}]', '[{\"word\": \"assistant\", \"note_vi\": \"assistant là người trợ lý; assistance là danh từ trừu tượng chỉ sự giúp đỡ\"}]', '[{\"pos\": \"verb\", \"word\": \"assist\"}, {\"pos\": \"noun\", \"word\": \"assistant\"}, {\"pos\": \"adjective\", \"word\": \"assistive\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/assistance-cori-9e8a01f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/assistance-aru0-9e8a01f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/assistance-aru5-9e8a01f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/assistance-aru6-9e8a01f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/assistance-aru10-9e8a01f2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/assistance-aru9-9e8a01f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/assistance-aru3-9e8a01f2