('27adda90-eaae-576a-b44e-ca9015732fc3', '2a37052e-e854-5df4-aebd-58ca22610d12', '5b2a68ff-ffa6-5685-8606-5623d5f1f600', '051e7114-78e9-55d8-b256-f0843a188b27', 'adapt', 'UK: /əˈdæpt/ | US: /əˈdæpt/', 'B2', 'verb', 'thích nghi', 'to modify behavior or ideas to suit new conditions or surroundings', 'Employees must adapt to new changes.', 'Nhân viên phải thích nghi với những thay đổi mới.', '{\"en\": \"Employees must adapt quickly to the new software system implemented by the IT department.\", \"vi\": \"Nhân viên phải nhanh chóng thích nghi với hệ thống phần mềm mới do phòng CNTT triển khai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/adapt-ljspeech-40fe84e6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/adapt-cori-40fe84e6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/adapt-422949b1.webp', '[\"adjust\", \"acclimate\", \"modify\", \"conform\"]', '[\"resist\"]', '[{\"phrase\": \"adapt to changes\", \"meaning\": \"thích nghi với các thay đổi\"}, {\"phrase\": \"adapt well to\", \"meaning\": \"thích ứng tốt với\"}]', '[{\"word\": \"adopt\", \"note_vi\": \"nhận nuôi, chọn áp dụng một giải pháp/chính sách\"}, {\"word\": \"adept\", \"note_vi\": \"thành thạo, tinh thông (tính từ)\"}]', '[{\"pos\": \"noun\", \"word\": \"adaptation\"}, {\"pos\": \"adjective\", \"word\": \"adaptable\"}, {\"pos\": \"noun\", \"word\": \"adaptability\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/adapt-cori-40fe84e6.mp3\", \"/storage/v1/object/public/pronunciation/v2/adapt-aru0-40fe84e6.mp3\", \"/storage/v1/object/public/pronunciation/v2/adapt-aru5-40fe84e6.mp3\", \"/storage/v1/object/public/pronunciation/v2/adapt-aru6-40fe84e6.mp3\", \"/storage/v1/object/public/pronunciation/v2/adapt-aru10-40fe84e6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/adapt-aru9-40fe84e6.mp3\", \"/storage/v1/object/public/pronunciation/v2/adapt-aru3-40fe84e6.mp3\", \"/storage/v1/object/public/pronunciation/v2/adapt-aru7-40fe