('a0e40a26-6525-51c4-aa4b-6b38175e470d', '2a37052e-e854-5df4-aebd-58ca22610d12', '5fc7ba95-807d-57d0-aa08-f673d19bbfe8', '99c9bea4-1837-5924-9511-6d6aa7dcb1da', 'password', '/ˈpɑːswɜːd/', 'A2', 'noun', 'chuỗi ký tự bí mật dùng để truy cập hệ thống hoặc tài khoản.', 'a secret word or combination of letters and numbers used for computer access.', 'You must enter your security password to access the company portal.', 'Bạn phải nhập mật khẩu bảo mật của mình để truy cập vào cổng thông tin công ty.', '{\"en\": \"You must enter a valid username and password to access the corporate database.\", \"vi\": \"Bạn phải nhập tên người dùng và mật khẩu hợp lệ để truy cập cơ sở dữ liệu của công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/password-ljspeech-5baa61e4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/password-cori-5baa61e4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/password-e1369f01.webp', '[\"passcode\", \"keyword\"]', NULL, '[{\"phrase\": \"enter a password\", \"meaning\": \"nhập mật khẩu\"}, {\"phrase\": \"reset a password\", \"meaning\": \"đặt lại mật khẩu\"}]', '[{\"word\": \"passcode\", \"note_vi\": \"thường chỉ gồm các con số (mã PIN)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/password-cori-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru0-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru5-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru6-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru10-5baa61e4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/password-aru9-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru3-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru7-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru8-5baa61e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/password-aru2-5ba