('940f77cb-2837-585b-bb70-1c0d54998092', '2a37052e-e854-5df4-aebd-58ca22610d12', '5fc7ba95-807d-57d0-aa08-f673d19bbfe8', '99c9bea4-1837-5924-9511-6d6aa7dcb1da', 'depart', '/dɪˈpɑːt/', 'B1', 'verb', 'Rời khỏi một nơi, thường là để bắt đầu một hành trình.', 'to leave a place, especially to start a journey to another destination.', 'Flight 402 is expected to depart on time despite the heavy rain.', 'Chuyến bay 402 dự kiến sẽ khởi hành đúng giờ bất chấp trời mưa to.', '{\"en\": \"The shuttle bus will depart from the hotel lobby every thirty minutes.\", \"vi\": \"Xe đưa đón sẽ khởi hành từ sảnh khách sạn mỗi ba mươi phút.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/depart-ljspeech-147bc781.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/depart-cori-147bc781.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/depart-c60d9c66.webp', '[\"leave\", \"go\", \"exit\"]', '[\"arrive\", \"enter\"]', '[{\"phrase\": \"depart for\", \"meaning\": \"khởi hành đi đâu\"}, {\"phrase\": \"depart from\", \"meaning\": \"khởi hành từ đâu\"}]', '[{\"word\": \"department\", \"note_vi\": \"department là phòng ban, depart là động từ khởi hành.\"}]', '[{\"pos\": \"noun\", \"word\": \"departure\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/depart-cori-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru0-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru5-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru6-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru10-147bc781.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/depart-aru9-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru3-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru7-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru8-147bc781.mp3\", \"/storage/v1/object/public/pronunciation/v2/depart-aru2-147bc781.mp3\"]}