('79779bac-105e-565c-94f2-b96fcf54405d', '2a37052e-e854-5df4-aebd-58ca22610d12', '7b7c3239-a89c-5be5-a030-fc84451d969d', '36258a0a-3e8d-5e74-bbe5-17be5ae4bb0a', 'designated', 'UK: /ˈdɛzɪɡˌneɪtɪd/ | US: /ˈdɛzɪɡˌneɪtɪd/', 'B2', 'adjective', 'được chỉ định', 'Officially chosen or specified for a particular use, task, or responsibility.', 'Please use the designated parking area.', 'Vui lòng sử dụng khu vực đỗ xe được chỉ định.', '{\"en\": \"Employees must park their vehicles only in the designated staff parking area.\", \"vi\": \"Nhân viên chỉ được đỗ xe tại khu vực đỗ xe dành riêng cho nhân viên đã được quy định.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/designated-ljspeech-03b951fe.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/designated-cori-03b951fe.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/designated-eedb6eee.webp', '[\"specified\", \"assigned\", \"reserved\"]', '[\"unassigned\", \"unrestricted\"]', '[{\"phrase\": \"designated area\", \"meaning\": \"khu vực được chỉ định\"}, {\"phrase\": \"designated driver\", \"meaning\": \"người lái xe được chỉ định\"}]', '[{\"word\": \"delegated\", \"note_vi\": \"được giao quyền/ủy nhiệm làm nhiệm vụ, khác với designated (được chỉ định/dành riêng)\"}]', '[{\"pos\": \"verb\", \"word\": \"designate\"}, {\"pos\": \"noun\", \"word\": \"designation\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/designated-cori-03b951fe.mp3\", \"/storage/v1/object/public/pronunciation/v2/designated-aru0-03b951fe.mp3\", \"/storage/v1/object/public/pronunciation/v2/designated-aru5-03b951fe.mp3\", \"/storage/v1/object/public/pronunciation/v2/designated-aru6-03b951fe.mp3\", \"/storage/v1/object/public/pronunciation/v2/designated-aru10-03b951fe.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/designated-aru9-03b951fe.mp3\", \"/storage/v1/object/public/pronunciation/v2/designated-aru3-03b951fe.mp3\", \"/storage/v1/object/public/pronunciation/v2/designated-