('73bf36fe-bb72-5c7a-973e-ed72cb23addb', '2a37052e-e854-5df4-aebd-58ca22610d12', 'cb929931-230f-5604-bd9b-39e8c3e2e97c', '16b65943-6c8a-5dbc-ae54-e2e416000a40', 'ambulance', '/ˈæmbjələns/', 'A2', 'noun', 'Xe chuyên dụng chở người bệnh hoặc bị thương đến bệnh viện.', 'a special vehicle used for taking sick or injured people quickly to the hospital.', 'The ambulance arrived promptly to rush the injured worker to the hospital.', 'Xe cứu thương đã đến kịp thời để đưa người công nhân bị thương vào viện.', '{\"en\": \"An ambulance arrived at the construction site to assist the worker who got injured.\", \"vi\": \"Một chiếc xe cứu thương đã đến công trường để hỗ trợ người công nhân bị thương.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ambulance-ljspeech-d036c133.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ambulance-cori-d036c133.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/ambulance-865d36d3.webp', '[\"emergency vehicle\"]', NULL, '[{\"phrase\": \"call an ambulance\", \"meaning\": \"gọi xe cứu thương\"}, {\"phrase\": \"ambulance service\", \"meaning\": \"dịch vụ xe cứu thương\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ambulance-cori-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru0-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru5-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru6-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru10-d036c133.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/ambulance-aru9-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru3-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru7-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru8-d036c133.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambulance-aru2-d036c133.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/