('66c5a741-ca1d-5e61-b09c-29673cea9698', '2a37052e-e854-5df4-aebd-58ca22610d12', 'dbde7c6f-e08b-5d91-8438-f4990a8a6008', 'e7306ae8-f8a6-577d-8c36-d04fd6721aae', 'courier', 'UK: /ˈkʊriə/ | US: /ˈkʊriər/', 'B2', 'noun', 'người đưa thư, chuyển phát nhanh', 'a person or company employed to transport urgent messages, packages, or important mail', 'Please send the documents by courier service.', 'Vui lòng gửi tài liệu bằng dịch vụ chuyển phát nhanh.', '{\"en\": \"The signed contract was delivered to our legal office by express courier.\", \"vi\": \"Hợp đồng đã ký được gửi đến văn phòng luật của chúng tôi bằng dịch vụ chuyển phát nhanh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courier-ljspeech-023daeb6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courier-cori-023daeb6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/courier-d3e13e61.webp', '[\"messenger\", \"carrier\", \"dispatcher\", \"runner\"]', NULL, '[{\"phrase\": \"express courier\", \"meaning\": \"chuyển phát nhanh\"}, {\"phrase\": \"courier service\", \"meaning\": \"dịch vụ chuyển phát\"}]', '[{\"word\": \"carrier\", \"note_vi\": \"hãng vận tải, công ty viễn thông\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/courier-cori-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru0-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru5-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru6-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru10-023daeb6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/courier-aru9-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru3-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru7-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru8-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru2-023daeb6.mp3\"]}, \"us\": {\"nu\": [\"/