('c1e56ab8-19a9-5bcd-ad94-78fcd14f52a0', '62f0e566-4773-5470-a53e-c003eb8647cf', '0b26ef8c-3640-59e9-81d8-0cd7cf00dc04', 'a78519cd-b1c4-5607-a92d-4cb761975521', 'oversize', 'UK: /ˌəʊvəˈsaɪzd/ | US: /ˌoʊvərˈsaɪzd/', 'B2', 'adjective', 'quá khổ', 'larger than the standard, usual, or expected dimensions or physical size', 'They had to use a special truck for the oversized cargo.', 'Họ phải dùng xe tải đặc biệt cho hàng hóa quá khổ.', '{\"en\": \"An extra fee will be charged for oversize luggage on international flights.\", \"vi\": \"Khoản phí bổ sung sẽ được tính cho hành lý quá khổ trên các chuyến bay quốc tế.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/oversize-ljspeech-d9288fa4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/oversize-cori-d9288fa4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/oversize-49231d2c.webp', '[\"oversized\", \"giant\", \"huge\", \"outsized\"]', '[\"undersized\", \"standard\", \"compact\"]', '[{\"phrase\": \"oversize baggage\", \"meaning\": \"hành lý quá khổ\"}, {\"phrase\": \"oversize cargo\", \"meaning\": \"hàng hóa quá kích thước\"}]', '[{\"word\": \"overweight\", \"note_vi\": \"Quá trọng lượng/quá cân (khác oversize là quá kích thước)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/oversize-cori-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru0-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru5-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru6-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru10-d9288fa4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/oversize-aru9-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru3-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru7-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversize-aru8-d9288fa4.mp3\", \"/storage/v1/object/public/pronunciation/