('60ef752e-1688-5eb8-9b79-d1a149a717c8', '62f0e566-4773-5470-a53e-c003eb8647cf', '14000a4c-760f-5285-91b2-94d88e9079a1', 'e1ab5cd6-5da2-5b89-97a7-d1a1d4919cea', 'regime', '/reɪˈʒiːm/', 'B1', 'noun', 'Một hệ thống chính trị hoặc một chính phủ.', 'a government or system that controls a country.', 'The country was ruled by an authoritarian regime for many decades.', 'Đất nước này đã bị cai trị bởi một chế độ độc tài trong nhiều thập kỷ.', '{\"en\": \"The new trade regime reduced tariffs between the two nations.\", \"vi\": \"Chế độ thương mại mới đã giảm thuế quan giữa hai quốc gia.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/regime-ljspeech-814189e5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/regime-cori-814189e5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/regime-ba2feb75.webp', '[\"government\", \"administration\", \"system\"]', NULL, '[{\"phrase\": \"authoritarian regime\", \"meaning\": \"chế độ độc tài\"}, {\"phrase\": \"regime change\", \"meaning\": \"thay đổi chính phủ\"}, {\"phrase\": \"tax regime\", \"meaning\": \"chế độ thuế\"}]', '[{\"word\": \"regimen\", \"note_vi\": \"regimen là chế độ ăn/luyện tập, không phải chính phủ.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/regime-cori-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru0-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru5-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru6-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru10-814189e5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/regime-aru9-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru3-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru7-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru8-814189e5.mp3\", \"/storage/v1/object/public/pronunciation/v2/regime-aru2-814189e5.mp3\"]}, \"us\": {\"nu\