('ad2ae4a0-fa9e-5a4a-b76d-884ef977d305', '62f0e566-4773-5470-a53e-c003eb8647cf', '19c93a9c-0cf8-5df5-9d03-29f6d1d12551', '0dbd2711-ba6b-5d55-b04a-a057ce97f8cf', 'harmony', '/ˈhɑːməni/', 'B2', 'noun', 'sự hòa hợp, hòa thuận giữa các yếu tố hoặc con người.', 'a state of agreement or peaceful feeling among people or things.', 'The couple lived in perfect harmony for many years.', 'Cặp đôi đã sống trong sự hòa thuận hoàn hảo suốt nhiều năm.', '{\"en\": \"Good communication helps team members work together in complete harmony on complex projects.\", \"vi\": \"Giao tiếp tốt giúp các thành viên làm việc ăn ý với nhau trong các dự án phức tạp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/harmony-ljspeech-5343a781.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/harmony-cori-5343a781.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/harmony-b880b4ea.webp', '[\"concord\", \"unity\", \"agreement\"]', '[\"conflict\", \"discord\"]', '[{\"phrase\": \"in harmony with\", \"meaning\": \"hòa hợp với\"}, {\"phrase\": \"work in harmony\", \"meaning\": \"làm việc ăn ý\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"harmonious\"}, {\"pos\": \"verb\", \"word\": \"harmonize\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/harmony-cori-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru0-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru5-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru6-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru10-5343a781.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/harmony-aru9-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru3-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru7-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru8-5343a781.mp3\", \"/storage/v1/object/public/pronunciation/v2/harmony-aru2-5343a781.mp3\"]