('821a3874-7df7-5b97-ab65-aa973e768d84', '62f0e566-4773-5470-a53e-c003eb8647cf', '289f5db8-3633-5621-bf32-19d0d4666fce', 'bf0c8991-5c3f-5a3c-a1fa-eb2887259518', 'deduct', 'UK: /dɪˈdʌkt/ | US: /dɪˈdʌkt/', 'C1', 'verb', 'khấu trừ', 'To take away an amount or quantity from a total sum.', 'The company will deduct taxes from your salary.', 'Công ty sẽ khấu trừ thuế từ lương của bạn.', '{\"en\": \"Health insurance premiums will be deducted directly from your monthly paycheck.\", \"vi\": \"Phí bảo hiểm y tế sẽ được khấu trừ trực tiếp từ tiền lương hàng tháng của bạn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/deduct-ljspeech-adebab7e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/deduct-cori-adebab7e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/deduct-e7bf8000.webp', '[\"subtract\", \"withhold\", \"discount\"]', '[\"add\", \"include\"]', '[{\"phrase\": \"deduct expenses\", \"meaning\": \"khấu trừ chi phí\"}, {\"phrase\": \"deduct from salary\", \"meaning\": \"trừ vào lương\"}]', '[{\"word\": \"deduce\", \"note_vi\": \"suy luận, suy ra (khác với deduct là khấu trừ con số/tiền bạc)\"}]', '[{\"pos\": \"noun\", \"word\": \"deduction\"}, {\"pos\": \"adjective\", \"word\": \"deductible\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/deduct-cori-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru0-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru5-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru6-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru10-adebab7e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/deduct-aru9-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru3-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru7-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-aru8-adebab7e.mp3\", \"/storage/v1/object/public/pronunciation/v2/deduct-a