('e792baa5-d788-597a-a27e-69cfa438cc7f', '62f0e566-4773-5470-a53e-c003eb8647cf', '2e89aa07-2bfc-5410-9a3a-6875447ccbdd', '38b95549-adc0-5eb3-ad14-3f21a7c6d873', 'feedback', 'UK: /ˈfiːdbæk/ | US: /ˈfiːdbæk/', 'B2', 'noun', 'ý kiến phản hồi', 'Information about reactions to a product or performance used as a basis for improvement.', 'We welcome your feedback on our new product.', 'Chúng tôi hoan nghênh phản hồi của bạn về sản phẩm mới của chúng tôi.', '{\"en\": \"Management relies heavily on customer feedback to continuously enhance product quality.\", \"vi\": \"Ban quản lý phụ thuộc rất nhiều vào ý kiến phản hồi của khách hàng để liên tục nâng cao chất lượng sản phẩm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/feedback-ljspeech-ef15f48c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/feedback-cori-ef15f48c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/feedback-f743a190.webp', '[\"response\", \"comments\", \"input\", \"evaluation\"]', NULL, '[{\"phrase\": \"constructive feedback\", \"meaning\": \"phản hồi mang tính xây dựng\"}, {\"phrase\": \"customer feedback\", \"meaning\": \"phản hồi từ khách hàng\"}, {\"phrase\": \"provide feedback\", \"meaning\": \"đưa ra phản hồi\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/feedback-cori-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru0-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru5-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru6-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru10-ef15f48c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/feedback-aru9-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru3-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru7-ef15f48c.mp3\", \"/storage/v1/object/public/pronunciation/v2/feedback-aru8-ef15f48c.mp3\", \"/storage/v1/object/public/pro