('ed8d6622-bb84-56de-9478-d1ed992ed399', '62f0e566-4773-5470-a53e-c003eb8647cf', '4e58d36e-4db3-58bb-bc0f-0ba698815db4', 'f7d2898d-cfc0-5345-9da8-389f2d0431f4', 'stake', '/steɪk/', 'B2', 'noun', 'Một cây cọc nhọn đóng xuống đất.', 'a pointed piece of wood or metal that is pushed into the ground to hold something.', 'They drove a wooden stake into the ground to anchor the tent.', 'Họ đóng một cây cọc gỗ xuống đất để cố định cái lều.', '{\"en\": \"The maintenance crew used metal stakes to secure the outdoor signage before the event.\", \"vi\": \"Đội bảo trì đã dùng cọc kim loại để cố định biển hiệu ngoài trời trước sự kiện.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/stake-ljspeech-2f6c8f6b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/stake-cori-2f6c8f6b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/stake-448c1aa5.webp', '[\"post\", \"pole\", \"peg\"]', NULL, '[{\"phrase\": \"wooden stake\", \"meaning\": \"cọc gỗ\"}, {\"phrase\": \"drive a stake\", \"meaning\": \"đóng cọc xuống đất\"}, {\"phrase\": \"tent stake\", \"meaning\": \"cọc lều\"}]', '[{\"word\": \"steak\", \"note_vi\": \"steak là thịt bò bít tết, stake là cọc nhọn hoặc cổ phần\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/stake-cori-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru0-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru5-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru6-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru10-2f6c8f6b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/stake-aru9-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru3-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru7-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru8-2f6c8f6b.mp3\", \"/storage/v1/object/public/pronunciation/v2/stake-aru2-2f6c8f6b.mp3\"]}, \"us\": {\"nu\": [\"/