('17b7fb91-830c-5282-8a84-35df14f7b1af', '62f0e566-4773-5470-a53e-c003eb8647cf', '4e58d36e-4db3-58bb-bc0f-0ba698815db4', 'f7d2898d-cfc0-5345-9da8-389f2d0431f4', 'shatter', '/ˈʃætə(r)/', 'B2', 'verb', 'làm vỡ thành nhiều mảnh nhỏ', 'to break suddenly and violently into many small pieces or destroy completely.', 'The glass vase shattered into a thousand pieces when it fell.', 'Chiếc bình thủy tinh vỡ tan thành nghìn mảnh khi nó rơi xuống.', '{\"en\": \"Falling sales figures completely shattered our hopes of hitting the quarterly goal.\", \"vi\": \"Doanh số giảm sút đã phá vỡ hoàn toàn hy vọng đạt mục tiêu quý của chúng tôi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/shatter-ljspeech-a5303239.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/shatter-cori-a5303239.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/shatter-90b612c9.webp', '[\"smash\", \"fracture\", \"break\"]', '[\"repair\", \"restore\"]', '[{\"phrase\": \"shatter confidence\", \"meaning\": \"làm vỡ vụn sự tự tin\"}, {\"phrase\": \"shatter hopes\", \"meaning\": \"dập tắt hy vọng\"}]', '[{\"word\": \"scatter\", \"note_vi\": \"Scatter là phân tán/rải rác, còn shatter là làm vỡ vụn.\"}]', '[{\"pos\": \"adjective\", \"word\": \"shattered\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/shatter-cori-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru0-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru5-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru6-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru10-a5303239.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/shatter-aru9-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru3-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru7-a5303239.mp3\", \"/storage/v1/object/public/pronunciation/v2/shatter-aru8-a5303239.mp3\", \"/storage/v1/object/public/pr