('1b56368a-af8a-5113-8bec-101d86274732', '62f0e566-4773-5470-a53e-c003eb8647cf', '51b5b4f5-ce1e-52d5-8b93-212c5f721df6', '9ad55d95-df7b-59de-b184-9729d0780819', 'testify', '/ˈtestɪfaɪ/', 'B1', 'verb', 'Đưa ra lời khai hoặc bằng chứng, đặc biệt tại tòa án.', 'to give a formal statement of what one knows in a legal case.', 'The witness refused to testify against his own family members.', 'Nhân chứng từ chối làm chứng chống lại các thành viên trong gia đình mình.', '{\"en\": \"The employee May testify about the safety violations during the court hearing.\", \"vi\": \"Nhân viên có thể đưa ra lời khai về các vi phạm an toàn trong phiên tòa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/testify-ljspeech-2aff7541.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/testify-cori-2aff7541.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/testify-21a754ee.webp', '[\"state\", \"declare\", \"attest\"]', NULL, '[{\"phrase\": \"testify against\", \"meaning\": \"đưa ra lời khai chống lại\"}, {\"phrase\": \"testify in court\", \"meaning\": \"khai báo tại tòa án\"}, {\"phrase\": \"testify under oath\", \"meaning\": \"khai dưới lời thề\"}]', '[{\"word\": \"testament\", \"note_vi\": \"testify là động từ khai báo, testament là danh từ di chúc\"}]', '[{\"pos\": \"noun\", \"word\": \"testimony\"}, {\"pos\": \"noun\", \"word\": \"testifier\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/testify-cori-2aff7541.mp3\", \"/storage/v1/object/public/pronunciation/v2/testify-aru0-2aff7541.mp3\", \"/storage/v1/object/public/pronunciation/v2/testify-aru5-2aff7541.mp3\", \"/storage/v1/object/public/pronunciation/v2/testify-aru6-2aff7541.mp3\", \"/storage/v1/object/public/pronunciation/v2/testify-aru10-2aff7541.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/testify-aru9-2aff7541.mp3\", \"/storage/v1/object/public/pronunciation/v2/testify-aru3-2aff7541.mp3\", \"/storage/v1/object/public/pronunciation/v2/testify-aru7-2