('20182f78-3411-5052-9fcf-3c39ab4ac539', '62f0e566-4773-5470-a53e-c003eb8647cf', '51f4441b-e8bf-5972-9860-1100ea64fdb7', '91bf1e19-74d1-5008-a872-f772f660cd83', 'recipient', '/rɪˈsɪpiənt/', 'B1', 'noun', 'người nhận một cái gì đó, như quà tặng, giải thưởng hoặc thông tin.', 'an individual or entity that officially receives or accepts something given to them.', 'All recipients of the scholarship must maintain a high GPA.', 'Tất cả những người nhận học bổng phải duy trì điểm trung bình cao.', '{\"en\": \"The recipient of the email should confirm receipt within two business days.\", \"vi\": \"Người nhận email nên xác nhận đã nhận trong vòng hai ngày làm việc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/recipient-ljspeech-dc00fa84.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/recipient-cori-dc00fa84.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/recipient-904bd125.webp', '[\"receiver\", \"addressee\", \"beneficiary\"]', '[\"sender\", \"giver\"]', '[{\"phrase\": \"award recipient\", \"meaning\": \"người nhận giải thưởng\"}, {\"phrase\": \"recipient list\", \"meaning\": \"danh sách người nhận\"}, {\"phrase\": \"intended recipient\", \"meaning\": \"người nhận dự kiến\"}]', '[{\"word\": \"reception\", \"note_vi\": \"recipient là người nhận, reception là sự đón tiếp\"}]', '[{\"pos\": \"verb\", \"word\": \"receive\"}, {\"pos\": \"noun\", \"word\": \"receipt\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/recipient-cori-dc00fa84.mp3\", \"/storage/v1/object/public/pronunciation/v2/recipient-aru0-dc00fa84.mp3\", \"/storage/v1/object/public/pronunciation/v2/recipient-aru5-dc00fa84.mp3\", \"/storage/v1/object/public/pronunciation/v2/recipient-aru6-dc00fa84.mp3\", \"/storage/v1/object/public/pronunciation/v2/recipient-aru10-dc00fa84.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/recipient-aru9-dc00fa84.mp3\", \"/storage/v1/object/public/pronunciation/v2/recipient-aru3-dc00fa84.mp3\", \"