('f5611f77-8f8d-5088-aa25-fcd76836bff6', '62f0e566-4773-5470-a53e-c003eb8647cf', '56008906-8741-5527-85f9-e370803ed4f2', '67af5de2-064d-5d53-ab87-037cb72d681d', 'casualty', '/ˈkæʒuəlti/', 'B2', 'noun', 'người chết hoặc bị thương trong tai nạn, chiến tranh.', 'a person who is injured or killed in an accident or war.', 'The earthquake resulted in many casualties, with hundreds injured and dozens dead.', 'Trận động đất đã gây ra nhiều thương vong, với hàng trăm người bị thương và hàng chục người thiệt mạng.', '{\"en\": \"The factory explosion resulted in only one minor casualty, thanks to quick evacuation.\", \"vi\": \"Vụ nổ nhà máy chỉ dẫn đến một thương vong nhỏ, nhờ vào việc sơ tán nhanh chóng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/casualty-ljspeech-f8f69957.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/casualty-cori-f8f69957.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/casualty-3656958b.webp', '[\"victim\", \"fatality\"]', NULL, '[{\"phrase\": \"civilian casualty\", \"meaning\": \"thương vong dân thường\"}, {\"phrase\": \"heavy casualties\", \"meaning\": \"thương vong nặng nề\"}]', '[{\"word\": \"casualness\", \"note_vi\": \"sự cẩu thả, không trang trọng.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/casualty-cori-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru0-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru5-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru6-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru10-f8f69957.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/casualty-aru9-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru3-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru7-f8f69957.mp3\", \"/storage/v1/object/public/pronunciation/v2/casualty-aru8-f8f69957.mp3\", \"/storage/v1/object/public/pronunciatio