('e15d4613-18a3-5d10-997e-420cfb5600ac', '62f0e566-4773-5470-a53e-c003eb8647cf', '5a4fefda-514c-5dcf-9f53-66ec9e7264f3', 'bc998eee-ed4b-5653-a198-63dc3469a329', 'prescribe', '/prɪˈskraɪb/', 'B1', 'verb', 'Bác sĩ ra lệnh dùng thuốc hoặc phương pháp điều trị.', 'to recommend or order a medicine or treatment for a patient.', 'The doctor prescribed antibiotics for her infection.', 'Bác sĩ đã kê đơn thuốc kháng sinh cho bệnh nhiễm trùng của cô ấy.', '{\"en\": \"The physician prescribed rest and medication for the stressed project manager.\", \"vi\": \"Bác sĩ đã kê đơn nghỉ ngơi và thuốc cho người quản lý dự án bị stress.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/prescribe-ljspeech-3a29d570.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/prescribe-cori-3a29d570.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/prescribe-f86baf68.webp', '[\"advise\", \"recommend\"]', NULL, '[{\"phrase\": \"prescribe medication\", \"meaning\": \"kê đơn thuốc\"}, {\"phrase\": \"prescribe treatment\", \"meaning\": \"chỉ định điều trị\"}, {\"phrase\": \"prescribe rest\", \"meaning\": \"chỉ định nghỉ ngơi\"}]', '[{\"word\": \"proscribe\", \"note_vi\": \"proscribe là cấm đoán, prescribe là kê đơn.\"}]', '[{\"pos\": \"noun\", \"word\": \"prescription\"}, {\"pos\": \"adjective\", \"word\": \"prescriptive\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/prescribe-cori-3a29d570.mp3\", \"/storage/v1/object/public/pronunciation/v2/prescribe-aru0-3a29d570.mp3\", \"/storage/v1/object/public/pronunciation/v2/prescribe-aru5-3a29d570.mp3\", \"/storage/v1/object/public/pronunciation/v2/prescribe-aru6-3a29d570.mp3\", \"/storage/v1/object/public/pronunciation/v2/prescribe-aru10-3a29d570.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/prescribe-aru9-3a29d570.mp3\", \"/storage/v1/object/public/pronunciation/v2/prescribe-aru3-3a29d570.mp3\", \"/storage/v1/object/public/pronunciation/v2/prescribe-aru7-3a29d570.mp3\", \"/st