INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('e8fef233-6ac9-57d9-8fc6-90e5c15957ed', '62f0e566-4773-5470-a53e-c003eb8647cf', '66692ded-f4ee-51aa-a192-61997b0c60cb', '0447b078-b703-5884-a19d-1682e2760202', 'guarantee', 'UK: /ˌɡærənˈtiː/ | US: /ˌɡærənˈtiː/', 'B2', 'verb', 'đảm bảo', 'to promise with certainty that a particular condition will be fulfilled or provided.', 'We guarantee same-day delivery for all orders.', 'Chúng tôi đảm bảo giao hàng trong ngày cho tất cả các đơn hàng.', '{\"en\": \"The contractor guarantees that the renovated office will be ready by next Monday.\", \"vi\": \"Nhà thầu đảm bảo rằng văn phòng được cải tạo sẽ sẵn sàng vào thứ Hai tuần tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/guarantee-ljspeech-e3fb6398.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/guarantee-cori-e3fb6398.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/guarantee-248b9fc2.webp', '[\"assure\", \"ensure\", \"promise\", \"warrant\"]', NULL, '[{\"phrase\": \"guarantee satisfaction\", \"meaning\": \"đảm bảo sự hài lòng\"}, {\"phrase\": \"guarantee quality\", \"meaning\": \"đảm bảo chất lượng\"}]', '[{\"word\": \"ensure\", \"note_vi\": \"Ensure là bảo đảm một việc gì đó xảy ra, còn guarantee thường mang ý nghĩa cam kết chính thức hoặc bảo hành sản phẩm.\"}]', '[{\"pos\": \"noun\", \"word\": \"guarantee\"}, {\"pos\": \"noun\", \"word\": \"guarantor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/guarantee-cori-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru0-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru5-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru6-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru10-e3fb6398.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/guarantee-aru9-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru3-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru7-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru8-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-aru2-e3fb6398.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/guarantee-ljspeech-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt408-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt138-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt624-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt396-e3fb6398.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/guarantee-lt498-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt132-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt288-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt42-e3fb6398.mp3\", \"/storage/v1/object/public/pronunciation/v2/guarantee-lt90-e3fb6398.mp3\"]}}', 'Thường đi với cấu trúc \'guarantee that + mệnh đề\' hoặc \'guarantee something to someone\'.', 'contracts', 1, 12),
('e6242d43-6f7e-561b-b2c6-7e93ec04f6c0', '62f0e566-4773-5470-a53e-c003eb8647cf', '66692ded-f4ee-51aa-a192-61997b0c60cb', '0447b078-b703-5884-a19d-1682e2760202', 'optimistic', 'UK: /ˌɒptɪˈmɪstɪk/ | US: /ˌɑptəˈmɪstɪk/', 'B2', 'adjective', 'lạc quan', 'Feeling positive and hopeful about the future or the success of something.', 'She is optimistic about the project\'s success.', 'Cô ấy lạc quan về sự thành công của dự án.', '{\"en\": \"The sales director is optimistic about reaching the annual revenue target.\", \"vi\": \"Giám đốc kinh doanh rất lạc quan về việc đạt được mục tiêu doanh thu hàng năm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/optimistic-ljspeech-f1913a74.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/optimistic-cori-f1913a74.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/optimistic-3908d4d6.webp', '[\"positive\", \"hopeful\", \"confident\"]', '[\"pessimistic\", \"gloomy\"]', '[{\"phrase\": \"optimistic about\", \"meaning\": \"lạc quan về\"}, {\"phrase\": \"optimistic outlook\", \"meaning\": \"triển vọng lạc quan\"}]', '[{\"word\": \"optimal\", \"note_vi\": \"\'optimal\' nghĩa là tối ưu/tốt nhất, còn \'optimistic\' mang nghĩa thái độ lạc quan.\"}]', '[{\"pos\": \"noun\", \"word\": \"optimism\"}, {\"pos\": \"adverb\", \"word\": \"optimistically\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/optimistic-cori-f1913a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/optimistic-aru0-f1913a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/optimistic-aru5-f1913a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/optimistic-aru6-f1913a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/optimistic-aru10-f1913a74.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/optimistic-aru9-f1913a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/optimistic-aru3-f1913a74.mp3\", \"/storage/v1/object/public/pronunciation/v2/optimistic-aru7-f1913a74.mp3\", \"/storage/v1