('f02104f8-178b-519c-877b-7f7fbeb7aad0', '62f0e566-4773-5470-a53e-c003eb8647cf', '6c4c1683-1477-5d00-b148-1a0e838b6ad2', '2a2a1092-bbc2-550c-9f78-4941c2a8bc16', 'pier', 'UK: /pɪə/ | US: /pɪr/', 'B2', 'noun', 'bến tàu, cầu tàu', 'a structure built out over water for boats to dock beside.', 'They walked along the pier at sunset.', 'Họ đi dọc theo bến tàu lúc hoàng hôn.', '{\"en\": \"The cargo vessel docked at the pier early this morning to unload container shipments.\", \"vi\": \"Tàu chở hàng đã cập bến cầu tàu sáng sớm nay để dỡ các lô hàng công-te-nơ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pier-ljspeech-dd6f6821.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pier-cori-dd6f6821.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pier-fa51bfe2.webp', '[\"dock\", \"quay\", \"wharf\", \"jetty\"]', NULL, '[{\"phrase\": \"dock at the pier\", \"meaning\": \"cập bến tại cầu tàu\"}, {\"phrase\": \"wooden pier\", \"meaning\": \"cầu tàu bằng gỗ\"}, {\"phrase\": \"along the pier\", \"meaning\": \"dọc theo cầu tàu\"}]', '[{\"word\": \"peer\", \"note_vi\": \"pier là cầu tàu, còn peer (danh từ) là đồng nghiệp/người cùng trang lứa, hoặc (động từ) là nhìn chăm chú.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pier-cori-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru0-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru5-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru6-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru10-dd6f6821.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pier-aru9-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru3-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru7-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru8-dd6f6821.mp3\", \"/storage/v1/object/public/pronunciation/v2/pier-aru2-dd6f6821.mp3\"]}, \"us\": {\"nu\": [\"