('cc982439-ca7b-519e-a477-275d135caa0b', '62f0e566-4773-5470-a53e-c003eb8647cf', '6c990281-735e-5aa0-9434-a596bc7fd806', '69e41474-634d-5cb7-9fcd-577f43c8dbc9', 'snap', '/snæp/', 'B2', 'verb', 'bẻ gãy hoặc đứt đột ngột', 'to break something suddenly with a sharp sound, or to become angry very quickly.', 'The dry branch snapped under the weight of the snow.', 'Cành cây khô gãy lìa dưới sức nặng của tuyết.', '{\"en\": \"The plastic handle of the suitcase snapped when the airport staff threw it onto the belt.\", \"vi\": \"Tay cầm bằng nhựa của chiếc vali bị gãy khi nhân viên sân bay ném nó lên băng chuyền.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/snap-ljspeech-603863e3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/snap-cori-603863e3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/snap-ae16a50b.webp', '[\"break\", \"crack\"]', '[\"mend\", \"repair\"]', '[{\"phrase\": \"snap shut\", \"meaning\": \"đóng sầm lại\"}, {\"phrase\": \"snap at someone\", \"meaning\": \"gắt gỏng với ai\"}]', '[{\"word\": \"snap\", \"note_vi\": \"Snap còn có nghĩa là chụp ảnh nhanh. (photo)\"}]', '[{\"pos\": \"adjective\", \"word\": \"snappy\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/snap-cori-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru0-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru5-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru6-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru10-603863e3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/snap-aru9-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru3-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru7-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru8-603863e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/snap-aru2-603863e3.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v