('c5860c78-8c60-5a66-8142-ade847ea5d18', '62f0e566-4773-5470-a53e-c003eb8647cf', '8b66d7bf-dade-507a-af84-2e2faa614ec3', 'e0532063-1233-5a7a-9f74-7a3880af410d', 'instantly', 'UK: /ˈɪnstəntli/ | US: /ˈɪnstəntli/', 'B2', 'adverb', 'ngay lập tức', 'happening without any delay at all, immediately after an event occurs.', 'The new software instantly updated all records.', 'Phần mềm mới ngay lập tức cập nhật tất cả các bản ghi.', '{\"en\": \"Online order confirmation emails are sent instantly after payment is processed.\", \"vi\": \"Email xác nhận đơn hàng trực tuyến được gửi ngay lập tức sau khi thanh toán được xử lý.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/instantly-ljspeech-083814db.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/instantly-cori-083814db.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/instantly-3bd6db9b.webp', '[\"immediately\", \"promptly\", \"at once\", \"directly\"]', '[\"eventually\", \"later\", \"gradually\"]', '[{\"phrase\": \"reply instantly\", \"meaning\": \"phản hồi ngay lập tức\"}, {\"phrase\": \"instantly recognizable\", \"meaning\": \"dễ dàng nhận ra ngay\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"instant\"}, {\"pos\": \"noun\", \"word\": \"instant\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/instantly-cori-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru0-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru5-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru6-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru10-083814db.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/instantly-aru9-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru3-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru7-083814db.mp3\", \"/storage/v1/object/public/pronunciation/v2/instantly-aru8-083814db.mp3\", \"/storage/v1/objec