('175ee464-c4b1-5159-b9ee-816d15ad3c92', '62f0e566-4773-5470-a53e-c003eb8647cf', '99787769-f5c6-50ff-b45b-e48cbe31d7a9', '6d3c63f2-809c-5052-b454-84ca782814be', 'apparatus', '/ˌæpəˈreɪtəs/', 'C1', 'noun', 'bộ máy, thiết bị, dụng cụ chuyên dụng', 'the technical equipment or tools needed for a particular activity or purpose.', 'The laboratory is equipped with advanced scientific apparatus for experiments.', 'Phòng thí nghiệm được trang bị bộ máy khoa học tiên tiến để thực hiện các thí nghiệm.', '{\"en\": \"Technicians inspected the safety apparatus before starting the annual factory maintenance.\", \"vi\": \"Các kỹ thuật viên đã kiểm tra thiết bị an toàn trước khi bắt đầu bảo trì nhà máy hàng năm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/apparatus-ljspeech-f62d888c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/apparatus-cori-f62d888c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/apparatus-82a88a76.webp', '[\"equipment\", \"device\", \"gear\"]', NULL, '[{\"phrase\": \"safety apparatus\", \"meaning\": \"thiết bị an toàn\"}, {\"phrase\": \"state apparatus\", \"meaning\": \"bộ máy nhà nước\"}]', '[{\"word\": \"apparel\", \"note_vi\": \"Apparel là trang phục, không phải thiết bị dụng cụ.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/apparatus-cori-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru0-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru5-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru6-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru10-f62d888c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/apparatus-aru9-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru3-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru7-f62d888c.mp3\", \"/storage/v1/object/public/pronunciation/v2/apparatus-aru8-f62d888c.mp3\", \"/storage