('8aa7b9ea-4365-5418-86b3-500cac220eee', '62f0e566-4773-5470-a53e-c003eb8647cf', '99787769-f5c6-50ff-b45b-e48cbe31d7a9', '6d3c63f2-809c-5052-b454-84ca782814be', 'prioritize', 'UK: /praɪˈɒr.ɪ.taɪz/ | US: /praɪˈɔr.ə.taɪz/', 'B2', 'verb', 'ưu tiên', 'to treat an item or task as more important than other available options', 'Managers must prioritize tasks to meet deadlines effectively.', 'Các nhà quản lý phải ưu tiên các nhiệm vụ để hoàn thành đúng thời hạn một cách hiệu quả.', '{\"en\": \"We need to prioritize customer inquiries that request urgent assistance.\", \"vi\": \"Chúng ta cần ưu tiên các yêu cầu từ khách hàng cần hỗ trợ gấp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/prioritize-ljspeech-6c241e40.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/prioritize-cori-6c241e40.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/prioritize-a789a4fd.webp', '[\"give precedence to\", \"highlight\", \"emphasize\"]', '[\"neglect\", \"ignore\", \"deprioritize\"]', '[{\"phrase\": \"prioritize workload\", \"meaning\": \"sắp xếp ưu tiên khối lượng công việc\"}, {\"phrase\": \"prioritize safety\", \"meaning\": \"đặt an toàn lên hàng đầu\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"priority\"}, {\"pos\": \"noun\", \"word\": \"prioritization\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/prioritize-cori-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/prioritize-aru0-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/prioritize-aru5-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/prioritize-aru6-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/prioritize-aru10-6c241e40.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/prioritize-aru9-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/prioritize-aru3-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/prioritize-aru7-6c241e40.mp3\", \"/storage/v1/object/public/pronunciation/v2/pr