('037644da-166d-5486-b4fd-c6f1a7f865cf', '62f0e566-4773-5470-a53e-c003eb8647cf', 'ce7f04fd-f211-5dc4-8803-09f93f153795', '1e470a9b-2283-5856-a068-de4750e8b883', 'listing', '/ˈlɪstɪŋ/', 'B1', 'noun', 'Một danh sách các mục hoặc thông tin được sắp xếp.', 'an arranged record of items or details for reference or sale.', 'The real estate agent provided a listing of all available apartments in the area.', 'Đại lý bất động sản đã cung cấp danh sách tất cả các căn hộ có sẵn trong khu vực.', '{\"en\": \"We checked the job listing on the company website yesterday.\", \"vi\": \"Chúng tôi đã xem danh sách tuyển dụng trên trang web của công ty vào hôm qua.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/listing-ljspeech-6eccfbe2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/listing-cori-6eccfbe2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/listing-0c58e6c8.webp', '[\"list\", \"catalog\", \"register\"]', NULL, '[{\"phrase\": \"job listing\", \"meaning\": \"danh sách việc làm\"}, {\"phrase\": \"property listing\", \"meaning\": \"danh sách bất động sản\"}, {\"phrase\": \"listing of\", \"meaning\": \"danh sách các\"}]', '[{\"word\": \"lifting\", \"note_vi\": \"lifting là việc nâng, phát âm gần listing\"}]', '[{\"pos\": \"verb\", \"word\": \"list\"}, {\"pos\": \"adjective\", \"word\": \"listed\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/listing-cori-6eccfbe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/listing-aru0-6eccfbe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/listing-aru5-6eccfbe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/listing-aru6-6eccfbe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/listing-aru10-6eccfbe2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/listing-aru9-6eccfbe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/listing-aru3-6eccfbe2.mp3\", \"/storage/v1/object/public/pronunciation/v2/listing-aru7-6eccfbe2.mp3\", \"/storage/v1/obj