('37f819ae-c3a9-5d62-9601-7a999f21fc26', '62f0e566-4773-5470-a53e-c003eb8647cf', 'd191e012-ccc1-5637-af4a-8d8dd1ee3278', '89f9e15a-d8fd-5b93-b49e-8bc1a071984f', 'license', '/ˈlaɪsns/', 'A2', 'noun', 'giấy tờ chính thức cho phép bạn làm điều gì đó.', 'an official document giving permission to do a certain activity.', 'The company has obtained an official business license from the local authorities.', 'Công ty đã nhận được giấy phép kinh doanh chính thức từ chính quyền địa phương.', '{\"en\": \"The restaurant must renew its business license before the end of March.\", \"vi\": \"Nhà hàng phải gia hạn giấy phép kinh doanh trước cuối tháng Ba.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/license-ljspeech-23457129.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/license-cori-23457129.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/license-65400bbd.webp', '[\"permit\", \"certificate\", \"authorization\"]', NULL, '[{\"phrase\": \"driver\'s license\", \"meaning\": \"bằng lái xe\"}, {\"phrase\": \"business license\", \"meaning\": \"giấy phép kinh doanh\"}, {\"phrase\": \"license plate\", \"meaning\": \"biển số xe\"}]', '[{\"word\": \"licence\", \"note_vi\": \"license Mỹ, licence Anh, cùng nghĩa giấy phép\"}]', '[{\"pos\": \"noun\", \"word\": \"licensing\"}, {\"pos\": \"noun\", \"word\": \"licensee\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/license-cori-23457129.mp3\", \"/storage/v1/object/public/pronunciation/v2/license-aru0-23457129.mp3\", \"/storage/v1/object/public/pronunciation/v2/license-aru5-23457129.mp3\", \"/storage/v1/object/public/pronunciation/v2/license-aru6-23457129.mp3\", \"/storage/v1/object/public/pronunciation/v2/license-aru10-23457129.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/license-aru9-23457129.mp3\", \"/storage/v1/object/public/pronunciation/v2/license-aru3-23457129.mp3\", \"/storage/v1/object/public/pronunciation/v2/license-aru7-23457129.mp3\", \"/stora