('fc6a14fe-b2f8-5470-ab15-471248ce965b', '62f0e566-4773-5470-a53e-c003eb8647cf', 'e954406b-00cc-591f-a139-bb07def60828', 'be540341-793b-5fe4-9d6f-7c7a0857bb72', 'nominate', '/ˈnɒmɪneɪt/', 'B2', 'verb', 'chính thức đề xuất ai đó cho một vị trí hoặc giải thưởng.', 'to officially suggest someone for a position, honor, or election.', 'She was nominated for the Best Actress award for her role in the film.', 'Cô ấy được đề cử cho giải Nữ diễn viên xuất sắc nhất nhờ vai diễn trong phim.', '{\"en\": \"The committee decided to nominate Ms. Green for the Employee of the Year award.\", \"vi\": \"Ủy ban đã quyết định đề cử cô Green cho giải thưởng Nhân viên của Năm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nominate-ljspeech-a75e01f4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nominate-cori-a75e01f4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/nominate-b500836f.webp', '[\"propose\", \"suggest\", \"recommend\"]', '[\"reject\", \"dismiss\"]', '[{\"phrase\": \"nominate someone for\", \"meaning\": \"đề cử ai đó cho cái gì\"}, {\"phrase\": \"nominate someone as\", \"meaning\": \"đề cử ai đó làm vị trí gì\"}]', '[{\"word\": \"appoint\", \"note_vi\": \"appoint là bổ nhiệm trực tiếp, nominate chỉ là đề cử\"}]', '[{\"pos\": \"noun\", \"word\": \"nomination\"}, {\"pos\": \"noun\", \"word\": \"nominee\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/nominate-cori-a75e01f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/nominate-aru0-a75e01f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/nominate-aru5-a75e01f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/nominate-aru6-a75e01f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/nominate-aru10-a75e01f4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/nominate-aru9-a75e01f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/nominate-aru3-a75e01f4.mp3\", \"/storage/v1/object/public/pronunciation/v2/nominate-aru7-a75e01f4.mp3\"