('54ee84b7-3092-5cff-8223-336fae9b9630', '62f0e566-4773-5470-a53e-c003eb8647cf', 'ec53b9a2-3878-5a90-bb3f-252ad9f63e15', '8bc152ed-2196-5303-9665-947cfaa3765b', 'superior', '/suːˈpɪəriə(r)/', 'B1', 'adjective', 'vượt trội, tốt hơn', 'of higher quality or rank than something else.', 'This brand of coffee has a superior taste.', 'Thương hiệu cà phê này có hương vị vượt trội.', '{\"en\": \"Our superior customer service helped increase client retention this year.\", \"vi\": \"Dịch vụ khách hàng vượt trội của chúng tôi giúp tăng giữ chân khách năm nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/superior-ljspeech-063dcf21.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/superior-cori-063dcf21.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/superior-5687ef1b.webp', '[\"better\", \"greater\"]', '[\"inferior\"]', '[{\"phrase\": \"superior quality\", \"meaning\": \"chất lượng vượt trội\"}, {\"phrase\": \"superior performance\", \"meaning\": \"hiệu suất tốt hơn\"}]', '[{\"word\": \"supervisor\", \"note_vi\": \"supervisor là người giám sát, không phải superior hơn hẳn\"}]', '[{\"pos\": \"noun\", \"word\": \"superiority\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/superior-cori-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru0-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru5-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru6-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru10-063dcf21.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/superior-aru9-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru3-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru7-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru8-063dcf21.mp3\", \"/storage/v1/object/public/pronunciation/v2/superior-aru2-063dcf21.mp3\"]}, \"us\": {\"nu\": [\"/storage/v