('ffe89fb4-d785-54ef-9601-ca7a698a1043', '62f0e566-4773-5470-a53e-c003eb8647cf', 'f656bae2-1285-5fd8-8ddf-6fa850d91f55', '6f366658-a670-55af-a8b0-f1956bcb7ea5', 'footage', '/ˈfʊtɪdʒ/', 'B2', 'noun', 'Các đoạn phim hoặc video được ghi lại.', 'a piece of film or video showing a particular event.', 'The security camera footage showed the suspect entering the building.', 'Cảnh quay từ camera an ninh cho thấy nghi phạm đi vào tòa nhà.', '{\"en\": \"The marketing team reviewed the video footage of the product launch event.\", \"vi\": \"Nhóm tiếp thị đã xem lại đoạn phim video về sự kiện ra mắt sản phẩm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/footage-ljspeech-09ed598d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/footage-cori-09ed598d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/footage-37181770.webp', '[\"film\", \"recording\", \"video\"]', NULL, '[{\"phrase\": \"security footage\", \"meaning\": \"cảnh quay an ninh\"}, {\"phrase\": \"raw footage\", \"meaning\": \"cảnh quay thô chưa chỉnh sửa\"}]', '[{\"word\": \"foot\", \"note_vi\": \"foot là bàn chân hoặc đơn vị đo lường\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/footage-cori-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru0-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru5-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru6-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru10-09ed598d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/footage-aru9-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru3-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru7-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru8-09ed598d.mp3\", \"/storage/v1/object/public/pronunciation/v2/footage-aru2-09ed598d.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/foo