('a579482c-f110-5e3b-9e98-7433475e5399', 'a0594a7a-b5fe-5595-ba88-03001d217110', '3272ab85-a35e-5dcb-b467-31b71e3a9553', 'd145cec5-2dc9-52d3-9d0e-27807438ed74', 'asset', 'UK: /ˈæset/ | US: /ˈæset/', 'B2', 'noun', 'tài sản', 'a useful or valuable item, person, or financial resource owned by an individual or business', 'The company has significant financial assets.', 'Công ty có tài sản tài chính đáng kể.', '{\"en\": \"Her fluency in three languages makes her a valuable asset to our international sales division.\", \"vi\": \"Sự thành thạo ba ngôn ngữ khiến cô ấy trở thành một tài sản quý giá cho bộ phận bán hàng quốc tế của chúng tôi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/asset-ljspeech-05fac943.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/asset-cori-05fac943.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/asset-b6bdf515.webp', '[\"property\", \"resource\", \"possession\", \"capital\"]', '[\"liability\"]', '[{\"phrase\": \"valuable asset\", \"meaning\": \"tài sản giá trị / nhân tố quý giá\"}, {\"phrase\": \"liquid assets\", \"meaning\": \"tài sản thanh khoản (tiền mặt/dễ đổi ra tiền)\"}]', '[{\"word\": \"access\", \"note_vi\": \"quyền truy cập, không phải tài sản.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/asset-cori-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru0-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru5-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru6-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru10-05fac943.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/asset-aru9-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru3-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru7-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru8-05fac943.mp3\", \"/storage/v1/object/public/pronunciation/v2/asset-aru2-05fac94