('716049d7-403d-53f6-a3a9-2671ee149c5f', 'a0594a7a-b5fe-5595-ba88-03001d217110', '5958337e-4c9f-57bc-b220-6a137dd1e581', 'f0df39e9-1703-5574-8b7b-08a9cc41b893', 'billboard', 'UK: /ˈbɪlbɔːd/ | US: /ˈbɪlˌbɔrd/', 'B2', 'noun', 'bảng quảng cáo lớn', 'a very large outdoor board used for displaying advertisements near roads', 'Many companies use billboards to promote their new products.', 'Nhiều công ty sử dụng bảng quảng cáo lớn để quảng bá sản phẩm mới của họ.', '{\"en\": \"The marketing team designed an eye-catching billboard to promote the new product along the highway.\", \"vi\": \"Đội ngũ tiếp thị đã thiết kế một bảng quảng cáo lớn bắt mắt dọc theo đường cao tốc để quảng bá cho sản phẩm mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/billboard-ljspeech-5a602278.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/billboard-cori-5a602278.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/billboard-bae947db.webp', '[\"hoarding\", \"bulletin\", \"signboard\"]', NULL, '[{\"phrase\": \"digital billboard\", \"meaning\": \"bảng quảng cáo điện tử\"}, {\"phrase\": \"roadside billboard\", \"meaning\": \"bảng quảng cáo ven đường\"}]', '[{\"word\": \"blackboard\", \"note_vi\": \"bảng đen dùng trong lớp học, khác với billboard là biển quảng cáo tấm lớn ngoài trời\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/billboard-cori-5a602278.mp3\", \"/storage/v1/object/public/pronunciation/v2/billboard-aru0-5a602278.mp3\", \"/storage/v1/object/public/pronunciation/v2/billboard-aru5-5a602278.mp3\", \"/storage/v1/object/public/pronunciation/v2/billboard-aru6-5a602278.mp3\", \"/storage/v1/object/public/pronunciation/v2/billboard-aru10-5a602278.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/billboard-aru9-5a602278.mp3\", \"/storage/v1/object/public/pronunciation/v2/billboard-aru3-5a602278.mp3\", \"/storage/v1/object/public/pronunciation/v2/billboard-aru7-5a602278.mp3\", \"/storage/v1/object/public/p