('21c7728b-31b1-531f-bf77-89600e0682a6', 'a0594a7a-b5fe-5595-ba88-03001d217110', '6326d28f-b036-5b76-ae44-9b94baa85139', '545dfc25-569f-52d0-9c1c-dc35ada8b8ea', 'behalf', '', 'B2', 'preposition', 'thay mặt cho', 'as a representative of or for the benefit of another person or group.', 'We accept this award on behalf of the entire team.', 'Chúng tôi nhận giải thưởng này thay mặt cho cả đội.', '{\"en\": \"Mr. Harrison signed the lease agreement on behalf of the regional branch manager.\", \"vi\": \"Ông Harrison đã ký hợp đồng thuê thay mặt cho giám đốc chi nhánh khu vực.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/behalf-ljspeech-45ba5108.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/behalf-cori-45ba5108.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/behalf-0541b3aa.webp', '[\"in place of\", \"representing\"]', NULL, '[{\"phrase\": \"on behalf of\", \"meaning\": \"thay mặt cho\"}, {\"phrase\": \"act on behalf of\", \"meaning\": \"hành động nhân danh\"}, {\"phrase\": \"speak on behalf of\", \"meaning\": \"phát biểu thay mặt cho\"}]', '[{\"word\": \"in front of\", \"note_vi\": \"ở phía trước (vị trí không gian)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/behalf-cori-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru0-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru5-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru6-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru10-45ba5108.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/behalf-aru9-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru3-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru7-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru8-45ba5108.mp3\", \"/storage/v1/object/public/pronunciation/v2/behalf-aru2-45ba5108.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/pub