('603afeb4-a14b-50cc-8f8b-b47d5f4a0f40', 'a0594a7a-b5fe-5595-ba88-03001d217110', '752e1bb3-8c68-5ab4-830c-9299f1cccd5b', 'c3878140-674f-5dd8-92c7-adee571863e9', 'nevertheless', '/ˌnɛvəðəˈlɛs/', 'B2', 'adverb', 'Tuy vậy; tuy nhiên.', 'despite what was just said, something else is still true.', 'The project budget was limited; nevertheless, the team delivered outstanding results.', 'Ngân sách dự án bị giới hạn; tuy vậy, đội ngũ vẫn đạt được kết quả xuất sắc.', '{\"en\": \"The meeting ran late; nevertheless, the team submitted the report on time.\", \"vi\": \"Cuộc họp kéo dài; tuy vậy, đội ngũ vẫn nộp báo cáo đúng hạn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nevertheless-ljspeech-80d7ab15.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/nevertheless-cori-80d7ab15.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/nevertheless-03799a2e.webp', '[\"however\", \"nonetheless\", \"still\"]', NULL, '[{\"phrase\": \"but nevertheless\", \"meaning\": \"nhưng tuy vậy\"}, {\"phrase\": \"nevertheless, still\", \"meaning\": \"tuy vậy, vẫn\"}]', '[{\"word\": \"nonetheless\", \"note_vi\": \"đồng nghĩa, hay bị nhầm chính tả với nevertheless\"}, {\"word\": \"never\", \"note_vi\": \"never nghĩa là không bao giờ, khác hoàn toàn\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/nevertheless-cori-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2/nevertheless-aru0-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2/nevertheless-aru5-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2/nevertheless-aru6-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2/nevertheless-aru10-80d7ab15.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/nevertheless-aru9-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2/nevertheless-aru3-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2/nevertheless-aru7-80d7ab15.mp3\", \"/storage/v1/object/public/pronunciation/v2