('358bc6a2-ac3c-5573-86c9-2e023119b9c1', 'a0594a7a-b5fe-5595-ba88-03001d217110', '752e1bb3-8c68-5ab4-830c-9299f1cccd5b', 'c3878140-674f-5dd8-92c7-adee571863e9', 'altogether', 'UK: /ˌɔːltəˈɡeðər/ | US: /ˌɔːltəˈɡeðər/', 'B2', 'adverb', 'tổng cộng, hoàn toàn', 'completely, or considering everything as a total sum or combined whole.', 'The project cost over a million dollars altogether.', 'Dự án tiêu tốn hơn một triệu đô la tổng cộng.', '{\"en\": \"The office renovation project cost $50,000 altogether.\", \"vi\": \"Dự án cải tạo văn phòng tốn tổng cộng 50.000 đô la.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/altogether-ljspeech-6c29a823.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/altogether-cori-6c29a823.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/altogether-a0f73d7b.webp', '[\"entirely\", \"completely\", \"in total\", \"fully\"]', '[\"partially\", \"partly\"]', '[{\"phrase\": \"altogether different\", \"meaning\": \"hoàn toàn khác biệt\"}, {\"phrase\": \"cost altogether\", \"meaning\": \"có giá tổng cộng\"}]', '[{\"word\": \"all together\", \"note_vi\": \"all together nghĩa là mọi người/mọi vật tập hợp cùng một nơi hoặc đồng thời làm gì.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/altogether-cori-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru0-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru5-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru6-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru10-6c29a823.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/altogether-aru9-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru3-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru7-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/altogether-aru8-6c29a823.mp3\", \"/storage/v1/object/public/pronunciation/v2/a