('dfa72fbf-a3ba-5859-b623-58f095ec157b', 'a0594a7a-b5fe-5595-ba88-03001d217110', '961c6053-5c01-5879-9c92-6a9e878dc464', '839210ac-bf23-53e8-a622-0d185259d9a5', 'autograph', 'UK: /ˈɔːtəɡrɑːf/ | US: /ˈɔːtəˌɡræf/', 'B2', 'noun', 'chữ ký của người nổi tiếng', 'a famous person\'s handwritten signature given to a fan or admirer as a keepsake', 'Fans waited for hours to get an autograph.', 'Người hâm mộ đã đợi hàng giờ để có được chữ ký.', '{\"en\": \"The keynote speaker signed autographs for attendees after her presentation.\", \"vi\": \"Diễn giả chính đã ký tặng cho các tham dự viên sau bài thuyết trình của cô.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/autograph-ljspeech-c7192247.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/autograph-cori-c7192247.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/autograph-22310a45.webp', '[\"signature\", \"endorsement\"]', NULL, '[{\"phrase\": \"sign an autograph\", \"meaning\": \"ký tặng kỷ niệm\"}, {\"phrase\": \"ask for an autograph\", \"meaning\": \"xin chữ ký người nổi tiếng\"}]', '[{\"word\": \"signature\", \"note_vi\": \"chữ ký dùng cho văn bản, tài liệu chính thức\"}]', '[{\"pos\": \"verb\", \"word\": \"autograph\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/autograph-cori-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru0-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru5-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru6-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru10-c7192247.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/autograph-aru9-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru3-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru7-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autograph-aru8-c7192247.mp3\", \"/storage/v1/object/public/pronunciation/v2/autog