('6507dbfe-f629-5643-ac80-2ac39dfc8b00', 'a0594a7a-b5fe-5595-ba88-03001d217110', '961c6053-5c01-5879-9c92-6a9e878dc464', '839210ac-bf23-53e8-a622-0d185259d9a5', 'appropriate', '/əˈprəʊpriət/', 'B1', 'adjective', 'Phù hợp, đúng đắn với một tình huống hoặc mục đích cụ thể.', 'suitable or right for a particular situation, event, or group of people.', 'This software is not appropriate for processing large amounts of financial data.', 'Phần mềm này không phù hợp để xử lý lượng lớn dữ liệu tài chính.', '{\"en\": \"All employees must wear appropriate business attire when meeting with potential investors.\", \"vi\": \"Tất cả nhân viên phải mặc trang phục công sở phù hợp khi gặp gỡ các nhà đầu tư tiềm năng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/appropriate-ljspeech-f290fd9a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/appropriate-cori-f290fd9a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/appropriate-d387d884.webp', '[\"suitable\", \"proper\", \"fitting\"]', '[\"inappropriate\", \"unsuitable\"]', '[{\"phrase\": \"appropriate action\", \"meaning\": \"hành động phù hợp\"}, {\"phrase\": \"appropriate dress\", \"meaning\": \"trang phục phù hợp\"}, {\"phrase\": \"appropriate measure\", \"meaning\": \"biện pháp thích hợp\"}]', '[{\"word\": \"appreciate\", \"note_vi\": \"appreciate nghĩa là đánh giá cao hoặc trân trọng.\"}]', '[{\"pos\": \"adverb\", \"word\": \"appropriately\"}, {\"pos\": \"noun\", \"word\": \"appropriateness\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/appropriate-cori-f290fd9a.mp3\", \"/storage/v1/object/public/pronunciation/v2/appropriate-aru0-f290fd9a.mp3\", \"/storage/v1/object/public/pronunciation/v2/appropriate-aru5-f290fd9a.mp3\", \"/storage/v1/object/public/pronunciation/v2/appropriate-aru6-f290fd9a.mp3\", \"/storage/v1/object/public/pronunciation/v2/appropriate-aru10-f290fd9a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/appropriate-aru9-f290fd9a.m