('5b5b27c6-228c-5080-be11-bfe473f3e80c', 'a0594a7a-b5fe-5595-ba88-03001d217110', '961c6053-5c01-5879-9c92-6a9e878dc464', '839210ac-bf23-53e8-a622-0d185259d9a5', 'county', '/ˈkaʊnti/', 'B1', 'noun', 'Một đơn vị hành chính địa phương lớn hơn thành phố nhưng nhỏ hơn bang.', 'a local administrative region bigger than a city but smaller than a state.', 'The new library is funded by the county government.', 'Thư viện mới được tài trợ bởi chính quyền hạt.', '{\"en\": \"The county issued a new business license to the local restaurant.\", \"vi\": \"Huyện đã cấp giấy phép kinh doanh mới cho nhà hàng địa phương.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/county-ljspeech-52d3663e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/county-cori-52d3663e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/county-21bb5f46.webp', '[\"district\", \"region\"]', NULL, '[{\"phrase\": \"county council\", \"meaning\": \"hội đồng quận/huyện\"}, {\"phrase\": \"county seat\", \"meaning\": \"thủ phủ của huyện\"}, {\"phrase\": \"county line\", \"meaning\": \"ranh giới huyện\"}]', '[{\"word\": \"country\", \"note_vi\": \"country là quốc gia, county là đơn vị hành chính địa phương\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/county-cori-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru0-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru5-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru6-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru10-52d3663e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/county-aru9-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru3-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru7-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru8-52d3663e.mp3\", \"/storage/v1/object/public/pronunciation/v2/county-aru2-52d3663e.mp3\"]}, \"us\"