('644f2905-b539-567f-a0b1-8de959b1a65c', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'a29ae110-c6ff-5064-973b-52de609618e7', 'f8f4efd3-6651-5a9e-aa1a-f6f1ff72c975', 'fee', '/fiː/', 'A2', 'noun', 'khoản tiền phải trả cho một dịch vụ hoặc quyền lợi.', 'an amount of money that you pay for professional advice or services.', 'The museum charges a small entrance fee for adults.', 'Bảo tàng thu một khoản phí vào cửa nhỏ đối với người lớn.', '{\"en\": \"The legal firm charges a high hourly fee for their consultation services to clients.\", \"vi\": \"Công ty luật tính phí theo giờ rất cao cho các dịch vụ tư vấn cho khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fee-ljspeech-9c15cdad.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fee-cori-9c15cdad.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/fee-1c19be33.webp', '[\"charge\", \"cost\", \"payment\"]', NULL, '[{\"phrase\": \"service fee\", \"meaning\": \"phí dịch vụ\"}, {\"phrase\": \"entrance fee\", \"meaning\": \"phí vào cửa\"}]', '[{\"word\": \"fare\", \"note_vi\": \"fare là phí đi lại (xe bus, tàu), fee là phí dịch vụ.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fee-cori-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru0-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru5-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru6-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru10-9c15cdad.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/fee-aru9-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru3-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru7-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru8-9c15cdad.mp3\", \"/storage/v1/object/public/pronunciation/v2/fee-aru2-9c15cdad.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fee-ljspeech-9c15cdad.mp3\", \"/storage/v1/object/