('0fe9bba7-8224-5e88-b618-633d2a1f8bdd', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'aefff331-dcf2-5945-99d0-87ca3b33511e', 'f095cddf-5e5d-5824-a989-cbbbc394e27a', 'owe', '/əʊ/', 'A2', 'verb', 'Có bổn phận phải trả lại tiền, hoặc mắc nợ ai đó điều gì.', 'to be required to pay money back to someone or give them something in return.', 'I still owe you five dollars from yesterday.', 'Tôi vẫn nợ bạn năm đô la từ hôm qua.', '{\"en\": \"The client still owes our company payment for three outstanding invoices.\", \"vi\": \"Khách hàng vẫn còn nợ công ty chúng tôi tiền thanh toán cho ba hóa đơn chưa giải quyết.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/owe-ljspeech-f66d5d14.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/owe-cori-f66d5d14.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/owe-af20c8da.webp', '[\"be indebted\", \"be obligated\"]', NULL, '[{\"phrase\": \"owe money\", \"meaning\": \"nợ tiền\"}, {\"phrase\": \"owe someone a favor\", \"meaning\": \"mắc nợ ai một ân huệ\"}, {\"phrase\": \"owe an apology\", \"meaning\": \"nợ lời xin lỗi\"}]', '[{\"word\": \"own\", \"note_vi\": \"own nghĩa là sở hữu, owe nghĩa là nợ — khác nhau hoàn toàn về nghĩa\"}]', '[{\"pos\": \"adjective\", \"word\": \"owing\"}, {\"pos\": \"noun\", \"word\": \"debt\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/owe-cori-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru0-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru5-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru6-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru10-f66d5d14.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/owe-aru9-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru3-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru7-f66d5d14.mp3\", \"/storage/v1/object/public/pronunciation/v2/owe-aru8-f66d5d14.mp3\", \"/storage/v1/object/pub