('55f815d3-adde-5183-96e4-562e1c644895', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'bbe56f0e-cb5b-5336-b031-e1c1b6087157', '8f9ba7f3-7b9c-51d9-88e3-1713d8839d0b', 'assortment', 'UK: /əˈsɔːtmənt/ | US: /əˈsɔːrtmənt/', 'B2', 'noun', 'tập hợp, hỗn hợp', 'a collection or mixture of various different items or types of the same general kind', 'The store offers a wide assortment of office supplies.', 'Cửa hàng cung cấp nhiều loại văn phòng phẩm.', '{\"en\": \"The bakery offers a wide assortment of fresh pastries every morning.\", \"vi\": \"Tiệm bánh cung cấp một sự lựa chọn đa dạng các loại bánh ngọt tươi mỗi sáng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assortment-ljspeech-fe0563bb.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assortment-cori-fe0563bb.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/assortment-c63cccdf.webp', '[\"variety\", \"selection\", \"mixture\", \"array\"]', '[\"monotony\", \"sameness\"]', '[{\"phrase\": \"a wide assortment of\", \"meaning\": \"một tập hợp đa dạng phong phú các...\"}, {\"phrase\": \"an assortment of goods\", \"meaning\": \"sự tổng hợp nhiều loại hàng hóa\"}]', '[{\"word\": \"assessment\", \"note_vi\": \"sự đánh giá, dễ nhầm vì chữ cái đầu giống nhau.\"}]', '[{\"pos\": \"adjective\", \"word\": \"assorted\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/assortment-cori-fe0563bb.mp3\", \"/storage/v1/object/public/pronunciation/v2/assortment-aru0-fe0563bb.mp3\", \"/storage/v1/object/public/pronunciation/v2/assortment-aru5-fe0563bb.mp3\", \"/storage/v1/object/public/pronunciation/v2/assortment-aru6-fe0563bb.mp3\", \"/storage/v1/object/public/pronunciation/v2/assortment-aru10-fe0563bb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/assortment-aru9-fe0563bb.mp3\", \"/storage/v1/object/public/pronunciation/v2/assortment-aru3-fe0563bb.mp3\", \"/storage/v1/object/public/pronunciation/v2/assortment-aru7-fe0563bb.mp3\", \"/storage/v1/object/public/pro