('cf4f539d-0922-5c0a-b36c-84b32ee7a1b6', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'c0c008b1-6e46-5bce-ae79-42ba058f0a18', '51b08fb6-813f-5cd4-b866-b675d14d7412', 'closure', 'UK: /ˈkləʊʒər/ | US: /ˈkloʊʒər/', 'B2', 'noun', 'sự đóng cửa, sự ngừng hoạt động', 'the permanent or temporary ending of operations at a business, facility, or event.', 'The company announced the closure of its factory.', 'Công ty thông báo việc đóng cửa nhà máy của mình.', '{\"en\": \"The temporary closure of the main bridge led to significant traffic delays during peak hours.\", \"vi\": \"Sự đóng cửa tạm thời của cây cầu chính đã dẫn đến việc ùn tắc giao thông nghiêm trọng trong giờ cao điểm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/closure-ljspeech-d091cefc.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/closure-cori-d091cefc.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/closure-de4bd457.webp', '[\"shutdown\", \"closing\", \"stoppage\", \"termination\"]', '[\"opening\", \"reopening\", \"launch\"]', '[{\"phrase\": \"road closure\", \"meaning\": \"sự đóng đường / phong tỏa đường\"}, {\"phrase\": \"temporary closure\", \"meaning\": \"sự đóng cửa tạm thời\"}, {\"phrase\": \"factory closure\", \"meaning\": \"sự đóng cửa nhà máy\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"close\"}, {\"pos\": \"adjective\", \"word\": \"closed\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/closure-cori-d091cefc.mp3\", \"/storage/v1/object/public/pronunciation/v2/closure-aru0-d091cefc.mp3\", \"/storage/v1/object/public/pronunciation/v2/closure-aru5-d091cefc.mp3\", \"/storage/v1/object/public/pronunciation/v2/closure-aru6-d091cefc.mp3\", \"/storage/v1/object/public/pronunciation/v2/closure-aru10-d091cefc.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/closure-aru9-d091cefc.mp3\", \"/storage/v1/object/public/pronunciation/v2/closure-aru3-d091cefc.mp3\", \"/storage/v1/object/public/pronunciation/v2/closure-aru7-d091cefc.mp