('1d85c127-c410-5372-a2de-dfb00c77234d', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'ec8bc830-7cb4-5d41-8952-737d5ae3ca42', '34f013c4-a87e-519a-92cf-4b5c260b2e92', 'root', '/ruːt/', 'B1', 'noun', 'Rễ cây; gốc rễ của vấn đề.', 'the basic cause or origin of a problem or a situation that needs attention.', 'The tree\'s roots spread deep into the soil.', 'Rễ cây lan sâu vào lòng đất.', '{\"en\": \"We need to find the root cause of the production delay to prevent it recurring.\", \"vi\": \"Chúng ta cần tìm ra nguyên nhân gốc rễ của sự chậm trễ sản xuất để ngăn chặn nó.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/root-ljspeech-dc76e9f0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/root-cori-dc76e9f0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/root-8ba95fb7.webp', '[\"origin\", \"source\"]', NULL, '[{\"phrase\": \"root cause\", \"meaning\": \"nguyên nhân gốc rễ\"}, {\"phrase\": \"at the root of\", \"meaning\": \"nguồn gốc của\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/root-cori-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru0-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru5-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru6-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru10-dc76e9f0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/root-aru9-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru3-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru7-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru8-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-aru2-dc76e9f0.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/root-ljspeech-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-lt408-dc76e9f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/root-lt138-dc76e9f0.mp3\", \"/storage