('a5af6698-8e26-5f7f-b5c5-0fb8177c62bd', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'fe63efa6-4c97-59d4-b4d8-509f7163391b', 'd9223ddd-0bbc-55ea-a580-721143783160', 'assign', 'UK: /əˈsaɪn/ | US: /əˈsaɪn/', 'B2', 'verb', 'phân công, giao (nhiệm vụ)', 'to give a specific duty, task, or responsibility to someone to carry out', 'The manager assigned tasks to the team members.', 'Người quản lý đã phân công nhiệm vụ cho các thành viên trong nhóm.', '{\"en\": \"The supervisor assigned the new project to the senior marketing specialist.\", \"vi\": \"Người giám sát đã giao dự án mới cho chuyên viên tiếp thị cao cấp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assign-ljspeech-9009b730.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assign-cori-9009b730.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/assign-80b45e6d.webp', '[\"allocate\", \"delegate\", \"appoint\", \"designate\"]', '[\"withdraw\", \"reclaim\"]', '[{\"phrase\": \"assign tasks\", \"meaning\": \"phân công nhiệm vụ\"}, {\"phrase\": \"assign a budget\", \"meaning\": \"phân bổ ngân sách\"}]', '[{\"word\": \"resign\", \"note_vi\": \"từ chức (hành động rời bỏ công việc, ngược lại với giao việc).\"}]', '[{\"pos\": \"noun\", \"word\": \"assignment\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/assign-cori-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru0-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru5-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru6-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru10-9009b730.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/assign-aru9-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru3-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru7-9009b730.mp3\", \"/storage/v1/object/public/pronunciation/v2/assign-aru8-9009b730.mp3\", \"/storage/v1/object/public/pronunciation