('e27f5ab5-a850-54ec-ab84-39b11e9ee959', 'a0594a7a-b5fe-5595-ba88-03001d217110', 'fe63efa6-4c97-59d4-b4d8-509f7163391b', 'd9223ddd-0bbc-55ea-a580-721143783160', 'compile', 'UK: /kəmˈpaɪl/ | US: /kəmˈpaɪl/', 'B2', 'verb', 'biên soạn, tổng hợp', 'to gather information from various sources and arrange it into a list or report', 'The team needs to compile all data for the presentation.', 'Nhóm cần tổng hợp tất cả dữ liệu để thuyết trình.', '{\"en\": \"The accounting team is compiling the financial report for the fourth quarter.\", \"vi\": \"Đội ngũ kế toán đang tổng hợp báo cáo tài chính cho quý bốn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/compile-ljspeech-36d0981b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/compile-cori-36d0981b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/compile-9bb339b9.webp', '[\"assemble\", \"gather\", \"collect\", \"organize\"]', '[\"disperse\", \"scatter\"]', '[{\"phrase\": \"compile data\", \"meaning\": \"tổng hợp dữ liệu\"}, {\"phrase\": \"compile a report\", \"meaning\": \"biên soạn một báo cáo\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"compilation\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/compile-cori-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru0-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru5-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru6-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru10-36d0981b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/compile-aru9-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru3-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru7-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru8-36d0981b.mp3\", \"/storage/v1/object/public/pronunciation/v2/compile-aru2-36d0981b.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2